-- ============================================================
-- GBC Work Hub — 해외사업운영팀 업무기록 이력 마이그레이션 (AURORA)
-- 원본: sql/해외사업운영팀 프로그램 작업내역_AURORA.xlsx
-- 생성: Claude Code (자동 변환 스크립트) — DBA 검토 후 실행.
-- 모델: 스프레드시트 1행 = MSDWHTKD_WRK_PRJ 1행. Ticket No가 채워진 행이
--       새 업무기록(MSDWHTKD_WRK) 헤더이며, 그 아래 Ticket No가 빈 행들은
--       같은 티켓의 추가 Type/Category/Project 그룹으로 묶인다.
-- 값 매핑:
--   PC(IP 형식) -> LOCAL_PC_IP, Person in charge -> PERSON_IN_CHARGE + AUTHOR_NM
--   TEAM_NM = '해외사업운영팀' 고정, WRITE_STATUS = 'COMPLETED', USR_ID = NULL(계정 연결 없음)
-- 복구 불가능한 날짜값("########", "상태 종료", 연도 없는 "8월20일" 등)은
-- 해당 날짜 컬럼을 NULL로 두고, 원본 텍스트를 같은 행의 코멘트에 [원본 ...] 형태로 보존한다.
-- CLIENT_KEY = 'XLSXIMPORT:사이트:티켓번호' 로 각 티켓을 표시해두고, 실행 시
-- 해당 CLIENT_KEY가 이미 있으면 건너뛴다 — 재실행해도 중복 삽입되지 않고,
-- 엑셀에 새로 추가된 티켓만 새로 들어간다.
-- ============================================================

SET DEFINE OFF;

DECLARE
    v_log_id   NUMBER;
    v_prj_id   NUMBER;
    v_exists   NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_exists FROM XSUP.MSDWHTKD_WRK WHERE CLIENT_KEY = 'XLSXIMPORT:AURORA:11541';
    IF v_exists = 0 THEN
    v_log_id := XSUP.SEQ_MSDWHTKD_WRK.NEXTVAL;
    INSERT INTO XSUP.MSDWHTKD_WRK (
        LOG_ID, CLIENT_KEY, SITE_CD, WRITE_STATUS, TICKET_NO, TICKET_CONTENTS, MENU_NM,
        PERSON_IN_CHARGE, LOCAL_PC_IP, START_DT, END_DT, DEPLOY_STATUS, DEPLOY_DT,
        WORK_COMMENT, CHANGESET_ID, AUTHOR_NM, TEAM_NM, CHANGED_FILE_COUNT,
        NEEDS_TICKET_REVIEW, CREATED_AT, UPDT_DTM
    ) VALUES (
        v_log_id, 'XLSXIMPORT:AURORA:11541', 'AURORA', 'COMPLETED', '11541', '가입원이 이중으로 가능했던 버그 수정.', 'Admission Ordered Patient List',
        '천근웅', '172.16.49.50', DATE '2024-11-13', NULL, '운영기', DATE '2024-11-28',
        NULL, 0, '천근웅', '해외사업운영팀', 1,
        'N', SYSTIMESTAMP, SYSTIMESTAMP
    );

    v_prj_id := XSUP.SEQ_MSDWHTKD_WRK_PRJ.NEXTVAL;
    INSERT INTO XSUP.MSDWHTKD_WRK_PRJ (
        PRJ_ID, LOG_ID, TYPE_NM, CATEGORY_NM, PROJECT_NM, SOURCE_ORIGIN,
        DEPLOY_STATUS, DEPLOY_DT, WORK_COMMENT, SORT_ORD, CREATED_AT, UPDT_DTM
    ) VALUES (
        v_prj_id, v_log_id, 'DB Object', 'Package', NULL, 'MANUAL',
        '운영기', DATE '2024-11-28', NULL, 0, SYSTIMESTAMP, SYSTIMESTAMP
    );
    INSERT INTO XSUP.MSDWHTKD_WRK_SRC (
        SRC_ID, LOG_ID, PRJ_ID, FILE_NM, TYPE_NM, CATEGORY_NM, PROJECT_NM,
        SOURCE_ORIGIN, IS_AUTO_CLASSIFIED, NEEDS_REVIEW, SORT_ORD, CREATED_AT, UPDT_DTM
    ) VALUES (
        XSUP.SEQ_MSDWHTKD_WRK_SRC.NEXTVAL, v_log_id, v_prj_id, 'xbil.pc_acp_acppraam_insert.sql', 'DB Object', 'Package', NULL,
        'MANUAL', 'N', 'N', 0, SYSTIMESTAMP, SYSTIMESTAMP
    );
    END IF;
END;
/

