        WORK_COMMENT, CHANGESET_ID, AUTHOR_NM, TEAM_NM, CHANGED_FILE_COUNT,
        NEEDS_TICKET_REVIEW, CREATED_AT, UPDT_DTM
    ) VALUES (
        v_log_id, 'XLSXIMPORT:AURORA:11933', 'AURORA', 'COMPLETED', '11933', '(Bug Fix) Aurora 운영기 간호일지 Date/Time 저장안됨', '간호일지',
        '이승철', '172.16.49.53', DATE '2025-02-17', NULL, '운영기', DATE '2025-02-20',
        NULL, 0, '이승철', '해외사업운영팀', 2,
